resolved as (
  select old.*,m.registry_version_code,
         leaf.code new_leaf_code,leaf.name new_leaf_name,
         skill.code new_skill_code,skill.name new_skill_name
  from canonical_map m
  join public.verified_question_diagnostic_taxonomy old on old.id=m.old_taxonomy_id
  join private.active_verified_question_diagnostic_taxonomy active on active.id=old.id
  join public.academic_skill_registry_nodes leaf
    on leaf.code=m.target_leaf_code and leaf.node_type='subskill' and leaf.status='active'
  join public.academic_skill_registry_nodes skill
    on skill.id=leaf.parent_id and skill.node_type='skill' and skill.status='active'
)
insert into public.verified_question_diagnostic_taxonomy(
  question_id,assessment_item_id,curriculum_mapping_id,question_content_hash,
  scope_code,objective_code,package_version,taxonomy_version,
  primary_skill_code,primary_skill_name,atomic_subskill_code,atomic_subskill_name,
  assessment_process_code,cognitive_process,evidence_statement,secondary_skill_codes,
  confidence_score,review_status,human_review_required,review_reason,
  supersedes_taxonomy_id,reviewed_by_authority,taxonomy_hash
)
select
  question_id,assessment_item_id,curriculum_mapping_id,question_content_hash,
  scope_code,objective_code,registry_version_code,
  registry_version_code||'-bank-'||substr(question_content_hash,1,12),
  new_skill_code,new_skill_name,new_leaf_code,new_leaf_name,
  assessment_process_code,cognitive_process,evidence_statement,'{}'::text[],
  confidence_score,'approved',false,
  'Canonical multi-subject registry migration from legacy taxonomy: '||
    primary_skill_name||' > '||atomic_subskill_name,
  id,'Brains Heist Platform Superadmin · Multi-Subject Registry Migration 2026-09-24',''
from resolved
where not exists(
  select 1 from public.verified_question_diagnostic_taxonomy successor
  where successor.supersedes_taxonomy_id=resolved.id
);

do $audit$
declare v_remaining integer;
begin
  select count(*) into v_remaining
  from private.active_verified_question_diagnostic_taxonomy t
  join public.questions q on q.id=t.question_id
  where lower(trim(q.subject)) in (
    'mathematics','maths','science','biology','chemistry','physics',
    'global perspectives','ict','geography',
    'german language','russian language','kyrgyz language','travel & tourism'
  )
  and not exists (
    select 1
    from public.academic_skill_registry_nodes leaf
    join public.academic_skill_registry_nodes skill on skill.id=leaf.parent_id
    join public.academic_skill_registry_versions v on v.id=leaf.registry_version_id
    join public.academic_skill_registry_subject_aliases a on a.registry_version_id=v.id
    join public.academic_skill_registry_nodes root on root.id=skill.parent_id
    where leaf.code=t.atomic_subskill_code
      and skill.code=t.primary_skill_code
      and leaf.node_type='subskill' and skill.node_type='skill'
      and a.alias_normalized=lower(trim(q.subject))
      and (a.allowed_strand_codes is null or root.code=any(a.allowed_strand_codes))
  );
  if v_remaining<>0 then
    raise exception 'multisubject_taxonomy_migration_incomplete: % active legacy rows remain',v_remaining;
  end if;
end;
$audit$;
